   254			}
   255	
   256			// Otherwise add handle to current node
   257			if n.handlers != nil {
   258				panic("handlers are already registered for path '" + fullPath + "'")
   259			}
   260			n.handlers = handlers
   261			n.fullPath = fullPath
   262			return
   263		}
   264	}
