129	// 		c.Error(errors.New("third"))
130	// 		c.Errors.Errors() // == []string{"first", "second", "third"}
131	func (a errorMsgs) Errors() []string {
132		if len(a) == 0 {
133			return nil
134		}
135		errorStrings := make([]string, len(a))
136		for i, err := range a {
