667	func redirectTrailingSlash(c *Context) {
668		req := c.Request
669		p := req.URL.Path
670		if prefix := path.Clean(c.Request.Header.Get("X-Forwarded-Prefix")); prefix != "." {
671			p = prefix + "/" + req.URL.Path
672		}
673		req.URL.Path = p + "/"
674		if length := len(p); length > 1 && p[length-1] == '/' {
675			req.URL.Path = p[:length-1]
676		}
677		redirectRequest(c)
