	fmt.Printf("1) before registering route: GET %s -> %d\n", path, w1.Code)

	// register the route at runtime, AFTER a request has been handled
	r.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
		c.String(http.StatusOK, "name=%q last_name=%q wild=%q",
			c.Param("name"), c.Param("last_name"), c.Param("wild"))
	})

