package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

const path = "/test/john/smith/is/super/great"

func get(r *gin.Engine, p string) (code int, body string) {
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, p, nil)
	r.ServeHTTP(w, req)
	return w.Code, w.Body.String()
}

func safeGet(r *gin.Engine, p string) (code int, body string, panicked any) {
	defer func() { panicked = recover() }()
	code, body = get(r, p)
	return
}

func main() {
	gin.SetMode(gin.TestMode)

	// ---- A) literal scenario: no routes at all before the first request ----
	func() {
		fmt.Println("== A) engine with NO routes; 1st GET 404; then register /test/:name/:last_name/*wild ==")
		r := gin.New()
		code, _ := get(r, path)
		fmt.Printf("   1st GET  -> %d\n", code)
		r.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
			c.String(200, "name=%q last=%q wild=%q", c.Param("name"), c.Param("last_name"), c.Param("wild"))
		})
		code, body, p := safeGet(r, path)
		fmt.Printf("   2nd GET  -> code=%d body=%q panic=%v\n", code, body, p)
	}()

	// ---- B) param-only route (no catchAll) ----
	func() {
		fmt.Println("== B) engine with NO routes; 1st GET 404; then register /test/:name/:last_name ==")
		r := gin.New()
		code, _ := get(r, path)
		fmt.Printf("   1st GET  -> %d\n", code)
		r.GET("/test/:name/:last_name", func(c *gin.Context) {
			c.String(200, "name=%q last=%q", c.Param("name"), c.Param("last_name"))
		})
		code, body, p := safeGet(r, "/test/john/smith")
		fmt.Printf("   2nd GET  -> code=%d body=%q panic=%v\n", code, body, p)
	}()

	// ---- C) unrelated param route registered up-front (maxParams=1 at 1st request) ----
	func() {
		fmt.Println("== C) engine with /user/:id up-front; 1st GET 404; then register /test/:name/:last_name/*wild ==")
		r := gin.New()
		r.GET("/user/:id", func(c *gin.Context) {})
		code, _ := get(r, path)
		fmt.Printf("   1st GET  -> %d\n", code)
		r.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
			c.String(200, "name=%q last=%q wild=%q", c.Param("name"), c.Param("last_name"), c.Param("wild"))
		})
		code, body, p := safeGet(r, path)
		fmt.Printf("   2nd GET  -> code=%d body=%q panic=%v\n", code, body, p)
	}()

	// ---- D) enough pre-existing params (maxParams>=3 at 1st request) ----
	func() {
		fmt.Println("== D) engine with /a/:x/:y/:z up-front (maxParams=3); 1st GET 404; then register /test/:name/:last_name/*wild ==")
		r := gin.New()
		r.GET("/a/:x/:y/:z", func(c *gin.Context) {})
		code, _ := get(r, path)
		fmt.Printf("   1st GET  -> %d\n", code)
		r.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
			c.String(200, "name=%q last=%q wild=%q", c.Param("name"), c.Param("last_name"), c.Param("wild"))
		})
		code, body, p := safeGet(r, path)
		fmt.Printf("   2nd GET  -> code=%d body=%q panic=%v\n", code, body, p)
	}()

	// ---- E) route registered BEFORE any request (control) ----
	func() {
		fmt.Println("== E) control: route registered before any request ==")
		r := gin.New()
		r.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
			c.String(200, "name=%q last=%q wild=%q", c.Param("name"), c.Param("last_name"), c.Param("wild"))
		})
		code, body, p := safeGet(r, path)
		fmt.Printf("   GET      -> code=%d body=%q panic=%v\n", code, body, p)
	}()

	// ---- F) real HTTP server, gin.Default() (Logger+Recovery), late registration ----
	func() {
		fmt.Println("== F) real httptest server + gin.Default(); 1st GET 404; then register route ==")
		r := gin.Default()
		srv := httptest.NewServer(r)
		defer srv.Close()
		resp, err := http.Get(srv.URL + path)
		fmt.Printf("   1st GET  -> err=%v status=%v\n", err, statusOf(resp))
		if resp != nil {
			resp.Body.Close()
		}
		r.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
			c.String(200, "name=%q last=%q wild=%q", c.Param("name"), c.Param("last_name"), c.Param("wild"))
		})
		resp2, err2 := http.Get(srv.URL + path)
		fmt.Printf("   2nd GET  -> err=%v status=%v\n", err2, statusOf(resp2))
		if resp2 != nil {
			b := make([]byte, 200)
			n, _ := resp2.Body.Read(b)
			fmt.Printf("   2nd body -> %q\n", string(b[:n]))
			resp2.Body.Close()
		}
	}()
}

func statusOf(r *http.Response) any {
	if r == nil {
		return "<nil>"
	}
	return r.StatusCode
}

