type myErr struct{ s string }

func (e *myErr) Error() string { return e.s }

func main() {
	inner := &myErr{"inner boom"}

	val := gin.Error{Err: inner, Type: gin.ErrorTypeAny} // VALUE
	wrappedVal := fmt.Errorf("wrap: %w", val)
	var t1 *myErr
	fmt.Printf("VALUE  gin.Error{...}: errors.Is(fmt.Errorf(\"%%w\", err), inner) = %v\n", errors.Is(wrappedVal, inner))
	fmt.Printf("VALUE  gin.Error{...}: errors.As(fmt.Errorf(\"%%w\", err), &target) = %v\n", errors.As(wrappedVal, &t1))

	ptr := &gin.Error{Err: inner, Type: gin.ErrorTypeAny} // POINTER
	wrappedPtr := fmt.Errorf("wrap: %w", ptr)
	var t2 *myErr
	fmt.Printf("POINTER &gin.Error{...}: errors.Is(fmt.Errorf(\"%%w\", err), inner) = %v\n", errors.Is(wrappedPtr, inner))
	fmt.Printf("POINTER &gin.Error{...}: errors.As(fmt.Errorf(\"%%w\", err), &target) = %v\n", errors.As(wrappedPtr, &t2))

	_, valUnwrap := interface{}(val).(interface{ Unwrap() error })
	_, ptrUnwrap := interface{}(ptr).(interface{ Unwrap() error })
	fmt.Printf("value implements interface{Unwrap() error}: %v ; pointer implements: %v\n", valUnwrap, ptrUnwrap)
}
