109	// stack returns a nicely formatted stack frame, skipping skip frames.
110	func stack(skip int) []byte {
111		buf := new(bytes.Buffer) // the returned data
112		// As we loop, we open files and read them. These variables record the currently
113		// loaded file.
114		var lines [][]byte
115		var lastFile string
116		for i := skip; ; i++ { // Skip the expected number of frames
117			pc, file, line, ok := runtime.Caller(i)
118			if !ok {
119				break
120			}
121			// Print this much at least.  If we can't find the source, it won't show.
122			fmt.Fprintf(buf, "%s:%d (0x%x)\n", file, line, pc)
123			if file != lastFile {
124				data, err := ioutil.ReadFile(file)
125				if err != nil {
126					continue
127				}
128				lines = bytes.Split(data, []byte{'\n'})
129				lastFile = file
130			}
131			fmt.Fprintf(buf, "\t%s: %s\n", function(pc), source(lines, line))
132		}
133		return buf.Bytes()
134	}
135	
136	// source returns a space-trimmed slice of the n'th line.
137	func source(lines [][]byte, n int) []byte {
138		n-- // in stack trace, lines are 1-indexed but our array is 0-indexed
139		if n < 0 || n >= len(lines) {
140			return dunno
141		}
142		return bytes.TrimSpace(lines[n])
143	}
144	
145	// function returns, if possible, the name of the function containing the PC.
146	func function(pc uintptr) []byte {
147		fn := runtime.FuncForPC(pc)
148		if fn == nil {
149			return dunno
150		}
151		name := []byte(fn.Name())
152		// The name includes the path name to the package, which is unnecessary
153		// since the file name is already included.  Plus, it has center dots.
154		// That is, we see
155		//	runtime/debug.*T·ptrmethod
156		// and want
157		//	*T.ptrmethod
158		// Also the package path might contain dot (e.g. code.google.com/...),
159		// so first eliminate the path prefix
160		if lastSlash := bytes.LastIndex(name, slash); lastSlash >= 0 {
161			name = name[lastSlash+1:]
162		}
163		if period := bytes.Index(name, dot); period >= 0 {
164			name = name[period+1:]
165		}
166		name = bytes.Replace(name, centerDot, dot, -1)
167		return name
168	}
