   688	// Recursive case-insensitive lookup function used by n.findCaseInsensitivePath
   689	func (n *node) findCaseInsensitivePathRec(path string, ciPath []byte, rb [4]byte, fixTrailingSlash bool) []byte {
   690		npLen := len(n.path)
   691	
   692	walk: // Outer loop for walking the tree
   693		for len(path) >= npLen && (npLen == 0 || strings.EqualFold(path[1:npLen], n.path[1:])) {
   694			// Add common prefix to result
   695			oldPath := path
   696			path = path[npLen:]
   697			ciPath = append(ciPath, n.path...)
   698	
   699			if len(path) == 0 {
   700				// We should have reached the node containing the handle.
   701				// Check if this node has a handle registered.
   702				if n.handlers != nil {
   703					return ciPath
   704				}
   705	
   706				// No handle found.
   707				// Try to fix the path by adding a trailing slash
   708				if fixTrailingSlash {
   709					for i, c := range []byte(n.indices) {
   710						if c == '/' {
   711							n = n.children[i]
   712							if (len(n.path) == 1 && n.handlers != nil) ||
   713								(n.nType == catchAll && n.children[0].handlers != nil) {
   714								return append(ciPath, '/')
   715							}
   716							return nil
   717						}
   718					}
   719				}
   720				return nil
   721			}
   722	
   723			// If this node does not have a wildcard (param or catchAll) child,
   724			// we can just look up the next child node and continue to walk down
   725			// the tree
   726			if !n.wildChild {
   727				// Skip rune bytes already processed
   728				rb = shiftNRuneBytes(rb, npLen)
   729	
   730				if rb[0] != 0 {
   731					// Old rune not finished
   732					idxc := rb[0]
   733					for i, c := range []byte(n.indices) {
   734						if c == idxc {
   735							// continue with child node
   736							n = n.children[i]
   737							npLen = len(n.path)
   738							continue walk
   739						}
   740					}
   741				} else {
   742					// Process a new rune
   743					var rv rune
   744	
   745					// Find rune start.
   746					// Runes are up to 4 byte long,
   747					// -4 would definitely be another rune.
   748					var off int
   749					for max := min(npLen, 3); off < max; off++ {
   750						if i := npLen - off; utf8.RuneStart(oldPath[i]) {
   751							// read rune from cached path
   752							rv, _ = utf8.DecodeRuneInString(oldPath[i:])
   753							break
   754						}
   755					}
   756	
   757					// Calculate lowercase bytes of current rune
   758					lo := unicode.ToLower(rv)
   759					utf8.EncodeRune(rb[:], lo)
   760	
   761					// Skip already processed bytes
   762					rb = shiftNRuneBytes(rb, off)
   763	
   764					idxc := rb[0]
   765					for i, c := range []byte(n.indices) {
   766						// Lowercase matches
   767						if c == idxc {
   768							// must use a recursive approach since both the
   769							// uppercase byte and the lowercase byte might exist
   770							// as an index
   771							if out := n.children[i].findCaseInsensitivePathRec(
   772								path, ciPath, rb, fixTrailingSlash,
   773							); out != nil {
   774								return out
   775							}
   776							break
   777						}
   778					}
   779	
   780					// If we found no match, the same for the uppercase rune,
   781					// if it differs
   782					if up := unicode.ToUpper(rv); up != lo {
   783						utf8.EncodeRune(rb[:], up)
   784						rb = shiftNRuneBytes(rb, off)
   785	
   786						idxc := rb[0]
   787						for i, c := range []byte(n.indices) {
   788							// Uppercase matches
   789							if c == idxc {
   790								// Continue with child node
   791								n = n.children[i]
   792								npLen = len(n.path)
   793								continue walk
   794							}
   795						}
   796					}
   797				}
   798	
   799				// Nothing found. We can recommend to redirect to the same URL
   800				// without a trailing slash if a leaf exists for that path
   801				if fixTrailingSlash && path == "/" && n.handlers != nil {
   802					return ciPath
   803				}
   804				return nil
   805			}
   806	
   807			n = n.children[0]
   808			switch n.nType {
   809			case param:
   810				// Find param end (either '/' or path end)
   811				end := 0
   812				for end < len(path) && path[end] != '/' {
   813					end++
   814				}
   815	
   816				// Add param value to case insensitive path
   817				ciPath = append(ciPath, path[:end]...)
   818	
   819				// We need to go deeper!
   820				if end < len(path) {
   821					if len(n.children) > 0 {
   822						// Continue with child node
   823						n = n.children[0]
   824						npLen = len(n.path)
   825						path = path[end:]
   826						continue
   827					}
