648	// Makes a case-insensitive lookup of the given path and tries to find a handler.
649	// It can optionally also fix trailing slashes.
650	// It returns the case-corrected path and a bool indicating whether the lookup
651	// was successful.
652	func (n *node) findCaseInsensitivePath(path string, fixTrailingSlash bool) ([]byte, bool) {
653		const stackBufSize = 128
654	
655		// Use a static sized buffer on the stack in the common case.
656		// If the path is too long, allocate a buffer on the heap instead.
657		buf := make([]byte, 0, stackBufSize)
658		if length := len(path) + 1; length > stackBufSize {
659			buf = make([]byte, 0, length)
660		}
661	
662		ciPath := n.findCaseInsensitivePathRec(
663			path,
664			buf,       // Preallocate enough memory for new path
665			[4]byte{}, // Empty rune buffer
666			fixTrailingSlash,
667		)
668	
669		return ciPath, ciPath != nil
670	}
