672	// Shift bytes in array by n bytes left
673	func shiftNRuneBytes(rb [4]byte, n int) [4]byte {
674		switch n {
675		case 0:
676			return rb
677		case 1:
678			return [4]byte{rb[1], rb[2], rb[3], 0}
679		case 2:
680			return [4]byte{rb[2], rb[3]}
681		case 3:
682			return [4]byte{rb[3]}
683		default:
684			return [4]byte{}
685		}
686	}
