package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"

	"github.com/gin-gonic/gin"
)

// ---------- reference matcher: segment trie, literal > param > catchall ----------

type rnode struct {
	lit      map[string]*rnode
	param    *rnode
	catchall *rnode
	handler  string
}

func newRnode() *rnode { return &rnode{lit: map[string]*rnode{}} }

func (n *rnode) insert(pattern string, handler string) bool {
	segs := strings.Split(pattern, "/")[1:] // pattern starts with '/'
	cur := n
	for i, s := range segs {
		switch {
		case strings.HasPrefix(s, ":"):
			if cur.param == nil {
				cur.param = newRnode()
			}
			cur = cur.param
		case strings.HasPrefix(s, "*"):
			if i != len(segs)-1 {
				return false
			}
			if cur.catchall == nil {
				cur.catchall = newRnode()
			}
			cur = cur.catchall
		default:
			if cur.lit[s] == nil {
				cur.lit[s] = newRnode()
			}
			cur = cur.lit[s]
		}
	}
	if cur.handler != "" {
		return false
	}
	cur.handler = handler
	return true
}

// match returns (handler, params, matched)
func (n *rnode) match(segs []string) (string, []string, bool) {
	// literal first
	if len(segs) == 0 {
		if n.handler != "" {
			return n.handler, nil, true
		}
		return "", nil, false
	}
	if c := n.lit[segs[0]]; c != nil {
		if h, p, ok := c.match(segs[1:]); ok {
			return h, p, true
		}
	}
	if n.param != nil {
		if h, p, ok := n.param.match(segs[1:]); ok {
			return h, append([]string{segs[0]}, p...), true
		}
	}
	if n.catchall != nil && n.catchall.handler != "" {
		return n.catchall.handler, []string{"/" + strings.Join(segs, "/")}, true
	}
	return "", nil, false
}

// tsr reports whether adding or removing a trailing slash would match
func (n *rnode) tsr(path string) bool {
	if path == "/" {
		return false
	}
	alt := path
	if strings.HasSuffix(path, "/") {
		alt = strings.TrimSuffix(path, "/")
	} else {
		alt = path + "/"
	}
	if alt == "" {
		return false
	}
	segs := strings.Split(alt, "/")[1:]
	_, _, ok := n.match(segs)
	return ok
}

// ---------- harness ----------

func ginResult(routes []string, path string) (res string, panicked any) {
	defer func() { panicked = recover() }()
	gin.SetMode(gin.TestMode)
	r := gin.New()
	for _, rt := range routes {
		pat := rt
		r.GET(pat, func(c *gin.Context) {
			c.String(200, pat)
		})
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil))
	if w.Code == 404 {
		return "404", nil
	}
	if w.Code == 301 || w.Code == 307 {
		return fmt.Sprintf("REDIR:%s", w.Header().Get("Location")), nil
	}
	return w.Body.String(), nil
}

func main() {
	pool := []string{
		"/a", "/b", "/a/b", "/a/c", "/a/:p", "/:p", "/:p/b", "/:p/c", "/:p/:q",
		"/a/:p/b", "/a/:p/c", "/a/b/:p", "/a/:p/:q", "/a/b/c", "/a/*w", "/:p/*w",
		"/a/b/*w", "/a/:p/*w", "/a/:p/:q/*w", "/x", "/x/y", "/x/:p", "/:p/:q/:r",
		"/a/b/c/d", "/a/:p/b/c", "/a/b/:p/c", "/a/b/c/:p", "/a/:p/:q/:r",
	}
	paths := []string{
		"/", "/a", "/b", "/c", "/a/", "/a/b", "/a/c", "/a/d", "/a/b/", "/a/b/c",
		"/a/b/c/d", "/a/b/c/d/e", "/a/x/y", "/x", "/x/y", "/x/y/z", "/a/x", "/a/x/y",
		"/a/x/y/z", "/a/x/y/z/w", "/a/b/c/d/e/f", "/a/b/x", "/a/x/b", "/a/x/b/c",
		"/a/b/x/c", "/a/b/c/x", "/a/x/y/z", "/z", "/z/y", "/a/z", "/a/b/c/d/e/f/g",
	}
	// route sets: all pairs and some triples from pool
	var sets [][]string
	for i := range pool {
		for j := range pool {
			if i == j {
				continue
			}
			sets = append(sets, []string{pool[i], pool[j]})
		}
	}
	// triples limited to a subset for speed
	sub := pool[:16]
	for i := range sub {
		for j := range sub {
			for k := range sub {
				if i == j || j == k || i == k {
					continue
				}
				sets = append(sets, []string{sub[i], sub[j], sub[k]})
			}
		}
	}
	fmt.Printf("route sets: %d\n", len(sets))
	mismatches := 0
	for _, routes := range sets {
		// build reference trie; skip sets the reference considers conflicting
		root := newRnode()
		okRef := true
		for _, rt := range routes {
			if !root.insert(rt, rt) {
				okRef = false
				break
			}
		}
		if !okRef {
			continue
		}
		// skip sets where gin panics on registration (wildcard conflicts)
		ginPanicked := false
		func() {
			defer func() {
				if p := recover(); p != nil {
					ginPanicked = true
				}
			}()
			gin.SetMode(gin.TestMode)
			r := gin.New()
			for _, rt := range routes {
				pat := rt
				r.GET(pat, func(c *gin.Context) { c.String(200, pat) })
			}
		}()
		if ginPanicked {
			continue
		}
		for _, p := range paths {
			got, pn := ginResult(routes, p)
			if pn != nil {
				fmt.Printf("PANIC routes=%v path=%s: %v\n", routes, p, pn)
				mismatches++
				continue
			}
			segs := strings.Split(p, "/")[1:]
			h, _, ok := root.match(segs)
			want := "404"
			if ok {
				want = h
			} else if root.tsr(p) {
				want = "TSR"
			}
			gotNorm := got
			if strings.HasPrefix(got, "REDIR:") {
				gotNorm = "TSR"
			}
			if gotNorm != want {
				// TSR vs 404 mismatch may be due to RedirectTrailingSlash subtleties; report all
				fmt.Printf("MISMATCH routes=%v path=%s gin=%q ref=%q\n", routes, p, got, want)
				mismatches++
				if mismatches > 60 {
					fmt.Println("... too many")
					return
				}
			}
		}
	}
	fmt.Printf("done, mismatches=%d\n", mismatches)
	_ = sort.Strings
}
