package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func get(r *gin.Engine, p string) (code int, body string, panicked any) {
	defer func() { panicked = recover() }()
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, p, nil))
	return w.Code, w.Body.String(), nil
}

type variant struct {
	name   string
	routes []string
	req    string
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	variants := []variant{
		{"A", []string{"/:a/x", "/b/y"}, "/b/x"},
		{"B", []string{"/:a/x/y/z", "/b/c/d/e"}, "/b/x/y/z"},
		{"C", []string{"/:a/:b/x", "/c/d/y"}, "/c/d/x"},
		{"D", []string{"/user/:id/x", "/user/static/y"}, "/user/static/x"},
		{"E", []string{"/:a/x", "/b/y", "/b/z"}, "/b/x"},
		{"F", []string{"/:a/:b/:c/d/e/f", "/g/h/i/j/k/l"}, "/g/h/i/j/d/e/f"},
	}
	for _, v := range variants {
		func() {
			defer func() {
				if p := recover(); p != nil {
					fmt.Printf("%s: PANIC %v\n", v.name, p)
				}
			}()
			r := gin.New()
			// 1st request: no routes -> 404, pooled context has cap(skippedNodes)==0
			code, _, _ := get(r, "/none")
			for _, rt := range v.routes {
				r.GET(rt, func(c *gin.Context) { c.String(200, "ok") })
			}
			code2, body, pan := get(r, v.req)
			fmt.Printf("%s: 1st=%d 2nd code=%d body=%q panic=%v routes=%v req=%s\n", v.name, code, code2, body, pan, v.routes, v.req)
		}()
	}
}
EOF
